<https://w3id.org/geolabs/ospd/data-types/data-type/stac-catalog/item> owl:sameAs <https://geolabs.github.io/bblocks-data-types/def/data-type/stac-catalog/item> ;
    rim:hasAction <https://w3id.org/geolabs/ospd/data-types/data-type/stac-catalog/actions/identifier-2026-11-17> .

